// Shim mínimo de mysql2/promise respaldado por node:sqlite, SOLO para pruebas locales sin red.
import { DatabaseSync } from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

function traducirEsquema(sql) {
  let s = sql;
  s = s.replace(/CREATE DATABASE[^;]*;/gi, '');
  s = s.replace(/USE\s+\w+;/gi, '');
  s = s.replace(/INT AUTO_INCREMENT PRIMARY KEY/gi, 'INTEGER PRIMARY KEY AUTOINCREMENT');
  s = s.replace(/ENUM\([^)]*\)/gi, 'TEXT');
  s = s.replace(/,\s*\n\s*INDEX \(ciclo, activa\)/i, '');
  return s;
}

function traducirConsulta(sql) {
  let s = sql;
  s = s.replace(/INSERT IGNORE INTO/gi, 'INSERT OR IGNORE INTO');
  s = s.replace(/GROUP_CONCAT\(([a-zA-Z0-9_.]+)\s+ORDER BY\s+[a-zA-Z0-9_.]+\s+SEPARATOR\s+('.*?')\)/gi, 'GROUP_CONCAT($1, $2)');
  // SQLite no admite UPDATE ... JOIN ... SET (sí es válido en MySQL real); se reescribe solo para esta prueba local.
  if (/UPDATE candidatura c JOIN oferta o ON o\.id = c\.id_oferta SET c\.estado = \? WHERE c\.id = \? AND o\.id_empresa = \?/.test(s)) {
    s = `UPDATE candidatura SET estado = ? WHERE id = ? AND id_oferta IN (SELECT id FROM oferta WHERE id_empresa = ?)`;
  }
  return s;
}

// Expande arrays de parámetros (usados en "IN (?)") a varios '?' seguidos, como hace mysql2 de verdad.
function expandir(sql, params) {
  let i = 0, out = [];
  const nuevaSql = sql.replace(/\?/g, () => {
    const v = params[i++];
    if (Array.isArray(v)) { out.push(...v); return `(${v.map(() => '?').join(',')})`; }
    out.push(v);
    return '?';
  });
  return [nuevaSql, out];
}

function normalizar(v) {
  if (v === undefined) return null;
  if (typeof v === 'boolean') return v ? 1 : 0;
  return v;
}

function ejecutar(db, sqlOriginal, params = []) {
  const [sqlExpandida, flat] = expandir(traducirConsulta(sqlOriginal), params);
  const vals = flat.map(normalizar);
  const esSelect = /^\s*(SELECT|WITH)/i.test(sqlExpandida);
  const stmt = db.prepare(sqlExpandida);
  try {
    if (esSelect) {
      const rows = stmt.all(...vals).map((r) => ({ ...r }));
      return [rows, undefined];
    }
    const r = stmt.run(...vals);
    return [{ insertId: Number(r.lastInsertRowid), affectedRows: r.changes }, undefined];
  } catch (e) {
    // mysql2 real usa e.code === 'ER_DUP_ENTRY' para violaciones de clave única; se iguala aquí.
    if (e.errcode === 2067 || /UNIQUE constraint failed/.test(e.message || '')) e.code = 'ER_DUP_ENTRY';
    throw e;
  }
}

function crearConexion(db) {
  return {
    async query(sql, params) { return ejecutar(db, sql, params); },
    async beginTransaction() { db.exec('BEGIN'); },
    async commit() { db.exec('COMMIT'); },
    async rollback() { try { db.exec('ROLLBACK'); } catch {} },
    release() {},
  };
}

export function createPool(config) {
  const db = new DatabaseSync(':memory:');
  db.exec('PRAGMA foreign_keys = ON;');
  const schemaPath = process.env.TEST_SCHEMA_PATH || path.resolve(__dirname, '../../sql/schema.sql');
  const schema = fs.readFileSync(schemaPath, 'utf8');
  db.exec(traducirEsquema(schema));
  console.log('[mysql2-shim] esquema SQLite cargado desde', schemaPath);

  return {
    async query(sql, params) { return ejecutar(db, sql, params); },
    async getConnection() { return crearConexion(db); },
    async end() {},
    _db: db,
  };
}

export default { createPool };
